package piglatin

import (
	"strings"
)

// Sentence translates an English sentence into Pig Latin.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, word := range words {
		words[i] = wordToPigLatin(word)
	}
	return strings.Join(words, " ")
}

// wordToPigLatin translates a single word into Pig Latin.
func wordToPigLatin(word string) string {
	// Rule 1: word begins with a vowel, "xr", or "yt" — just add "ay".
	if isVowel(word[0]) || strings.HasPrefix(word, "xr") || strings.HasPrefix(word, "yt") {
		return word + "ay"
	}

	// Find the end of the leading consonant cluster.
	n := len(word)
	i := 0
	for i < n {
		c := word[i]
		// A vowel ends the consonant cluster (Rules 2/4).
		if isVowel(c) {
			break
		}
		// Rule 3: "qu" is part of the consonant cluster.
		if c == 'q' && i+1 < n && word[i+1] == 'u' {
			i += 2
			break
		}
		// Rule 4: "y" after at least one consonant acts as a vowel.
		if c == 'y' && i > 0 {
			break
		}
		i++
	}

	return word[i:] + word[:i] + "ay"
}

// isVowel reports whether c is one of a, e, i, o, u.
func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

